test("同じ向きで範囲が重なり、位置の差がちょうど 8px なら、同じ線上に重なる", () => {
  expect(
    ThinLine.isCoinciding(
      { along: SidePairs.Vertical, at: 60, span: { min: 20, max: 60 } },
      { along: SidePairs.Vertical, at: 68, span: { min: 20, max: 30 } },
    ),
  ).toBe(true);
});

test("位置の差が 8.5px なら、同じ線上に重ならない", () => {
  expect(
    ThinLine.isCoinciding(
      { along: SidePairs.Vertical, at: 60, span: { min: 20, max: 60 } },
      { along: SidePairs.Vertical, at: 68.5, span: { min: 20, max: 30 } },
    ),
  ).toBe(false);
});

test("位置の大小を入れ替えても答えは同じ", () => {
  expect(
    ThinLine.isCoinciding(
      { along: SidePairs.Vertical, at: 68, span: { min: 20, max: 30 } },
      { along: SidePairs.Vertical, at: 60, span: { min: 20, max: 60 } },
    ),
  ).toBe(true);
});

test("向きが違う線は、位置の差が 0 で範囲が重なっていても、同じ線上に重ならない", () => {
  expect(
    ThinLine.isCoinciding(
      { along: SidePairs.Vertical, at: 60, span: { min: 20, max: 60 } },
      { along: SidePairs.Horizontal, at: 60, span: { min: 20, max: 60 } },
    ),
  ).toBe(false);
});

test("範囲が端で接するだけなら、位置の差が 0 でも、同じ線上に重ならない", () => {
  expect(
    ThinLine.isCoinciding(
      { along: SidePairs.Vertical, at: 60, span: { min: 20, max: 60 } },
      { along: SidePairs.Vertical, at: 60, span: { min: 60, max: 80 } },
    ),
  ).toBe(false);
});

test("範囲が離れていれば、位置の差が 0 でも、同じ線上に重ならない", () => {
  expect(
    ThinLine.isCoinciding(
      { along: SidePairs.Vertical, at: 60, span: { min: 20, max: 60 } },
      { along: SidePairs.Vertical, at: 60, span: { min: 70, max: 80 } },
    ),
  ).toBe(false);
});

test("揃え先と同じ相手までの距離が出ている向きでは、隙間を出さずガイド線は残す", () => {
  // 左辺が Below へ寄り（-2）、揃え先 Below との隙間（上下 20〜60）と下へ進んだ距離が同じ線になる
  const guides = snapGuidesAt({
    moving: Moving,
    parentBounds: Parent,
    siblings: [Below],
    measuresDistances: true,
  });

  // ガイド線は Below の左辺（左右 50）に、運んでいるもの（上下 10〜20）から Below まで引く
  expect(Option.unwrap(guides.horizontal)).toEqual({
    guideLine: { left: 49, top: 10, width: 2, height: 70 },
    gapLine: Option.none,
  });
});

test("揃え先より近い兄弟までの距離が、直交方向 5px の差で同じ線上に重なると、隙間を出さない", () => {
  // 隙間は左右 60、下へ進むと先に手前の兄弟（上下 30〜40）に当たる距離は左右 65
  const nearer = { left: 60, top: 30, width: 30, height: 10 };

  const guides = snapGuidesAt({
    moving: Moving,
    parentBounds: Parent,
    siblings: [Below, nearer],
    measuresDistances: true,
  });

  expect(Option.unwrap(guides.horizontal).gapLine).toEqual(Option.none);
});

test("直交方向の差がちょうど 8px の兄弟までの距離なら、隙間を出さない", () => {
  // 隙間は左右 60、手前の兄弟（左右 66〜120）までの距離は左右 68
  const nearer = { left: 66, top: 30, width: 54, height: 10 };

  const guides = snapGuidesAt({
    moving: Moving,
    parentBounds: Parent,
    siblings: [Below, nearer],
    measuresDistances: true,
  });

  expect(Option.unwrap(guides.horizontal).gapLine).toEqual(Option.none);
});

test("直交方向の差が 8px を超える兄弟までの距離なら、隙間を出したまま", () => {
  // 隙間は左右 60、手前の兄弟（左右 67〜120）までの距離は左右 68.5
  const nearer = { left: 67, top: 30, width: 53, height: 10 };

  const guides = snapGuidesAt({
    moving: Moving,
    parentBounds: Parent,
    siblings: [Below, nearer],
    measuresDistances: true,
  });

  expect(Option.unwrap(guides.horizontal).gapLine).toEqual(
    Option.some(BelowGap),
  );
});

test("親の縁との隙間も、同じ線上に重なる距離が出ていれば出さない", () => {
  /*
   * 親の下（外）にいて、左辺が親の左辺へ寄る（-0.9）。揃え先との隙間は親の下辺との間（上下
   * 100.8〜110）に出て、上へ進んだ距離も親の下辺に当たって同じ線になる。
   */
  const parentBounds = { left: 0.1, top: 0.1, width: 200.3, height: 100.7 };
  // 右へ進むと当たる兄弟（上下 80〜130）。辺も中心線も運んでいるものから 6 より離す
  const right = { left: 40, top: 80, width: 20, height: 50 };

  const guides = snapGuidesAt({
    moving: { left: 1, top: 110, width: 20, height: 10 },
    parentBounds,
    siblings: [right],
    measuresDistances: true,
  });

  expect(Option.unwrap(guides.horizontal).gapLine).toEqual(Option.none);
});

test("横に測った隙間も、同じ線上に重なる距離が出ていれば出さない", () => {
  // 上辺が右の兄弟（上下 32〜52）へ寄り（+2）、揃え先のその兄弟との隙間（左右 70〜120）が出る
  const right = { left: 120, top: 32, width: 30, height: 20 };

  const guides = snapGuidesAt({
    moving: { left: 50, top: 30, width: 20, height: 10 },
    parentBounds: Parent,
    siblings: [right],
    measuresDistances: true,
  });

  expect(Option.unwrap(guides.vertical).gapLine).toEqual(Option.none);
});

test("Alt / Option で距離を測らない回は、隙間をそのまま出す", () => {
  const guides = snapGuidesAt({
    moving: Moving,
    parentBounds: Parent,
    siblings: [Below],
    measuresDistances: false,
  });

  expect(Option.unwrap(guides.horizontal).gapLine).toEqual(
    Option.some(BelowGap),
  );
});

test("丸めると 0 になる 0.5px 未満の距離の線でも、同じ線上に重なれば隙間を出さない", () => {
  // 距離の線は上下 59.7〜60（長さ 0.3）で、隙間（上下 20〜60）と 0.3 だけ範囲が重なる
  const guides = RepositionLines.snapGuidesExceptCoincidingGaps({
    snap: { horizontal: Option.some(HandGuide), vertical: Option.none },
    distanceLines: {
      ...FacingDistances.None,
      vertical: {
        start: Option.none,
        end: Option.some({
          along: SidePairs.Vertical,
          at: 60,
          span: { min: 59.7, max: 60 },
        }),
      },
    },
  });

  expect(guides.horizontal).toEqual(
    Option.some({ guideLine: HandGuide.guideLine, gapLine: Option.none }),
  );
});

test("隙間と同じ向きの距離が反対側にあり範囲が離れているなら、隙間は出たまま", () => {
  const guides = RepositionLines.snapGuidesExceptCoincidingGaps({
    snap: { horizontal: Option.some(HandGuide), vertical: Option.none },
    distanceLines: {
      ...FacingDistances.None,
      vertical: {
        start: Option.some({
          along: SidePairs.Vertical,
          at: 60,
          span: { min: 0, max: 10 },
        }),
        end: Option.none,
      },
    },
  });

  expect(Option.unwrap(guides.horizontal).gapLine).toEqual(
    Option.some(BelowGap),
  );
});

test("直交する向きの距離が近い位置にあっても、隙間は出たまま", () => {
  const guides = RepositionLines.snapGuidesExceptCoincidingGaps({
    snap: { horizontal: Option.some(HandGuide), vertical: Option.none },
    distanceLines: {
      ...FacingDistances.None,
      horizontal: {
        start: Option.none,
        end: Option.some({
          along: SidePairs.Horizontal,
          at: 60,
          span: { min: 20, max: 60 },
        }),
      },
    },
  });

  expect(Option.unwrap(guides.horizontal).gapLine).toEqual(
    Option.some(BelowGap),
  );
});

test("座標を置き直す落とし方は、Alt / Option の距離をすべて答える", () => {
  const edit = DropEdit.reposition(
    "title",
    SampleRepositionTarget,
    SampleMeasuredRepositionLines,
  );

  expect(DropEdit.facingDistances(edit)).toEqual(SampleDistances);
});

test("座標を置き直す落とし方は、Alt / Option の距離と同じ線上に重なる隙間を除き、ガイド線は残したガイドを答える", () => {
  const edit = DropEdit.reposition(
    "title",
    SampleRepositionTarget,
    SampleMeasuredRepositionLines,
  );

  expect(DropEdit.snapGuides(edit)).toEqual({
    horizontal: Option.some({
      guideLine: SampleGuideLine,
      gapLine: Option.none,
    }),
    vertical: Option.none,
  });
});

test("揃え先との隙間と同じ線になる向きにも、距離を出す", () => {
  expect(ArtboardDrag.facingDistances(draggingAlignedWithAbove())).toEqual({
    horizontal: {
      start: Option.none,
      end: Option.some({
        along: SidePairs.Horizontal,
        at: 120,
        span: { min: 400, max: 450 },
      }),
    },
    vertical: {
      start: Option.some({
        along: SidePairs.Vertical,
        at: 250,
        span: { min: -50, max: 40 },
      }),
      end: Option.none,
    },
  });
});

test("同じ線の距離が出ているとき、ガイドはガイド線を残して隙間を出さない", () => {
  const guides = ArtboardDrag.snapGuides(draggingAlignedWithAbove());

  // ガイド線は上の相手の左辺（左右 200）に、上の相手から運んでいるものまで引く
  expect(Option.unwrap(guides.horizontal)).toEqual({
    guideLine: { left: 199, top: -100, width: 2, height: 240 },
    gapLine: Option.none,
  });
});

test("Alt を押して運んでいる間、距離と同じ線上に重なる揃え先との隙間は出さず、ガイド線は出したまま", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();

  // `marker` との隙間 116 は、下の `card` までの距離 66 と同じ線上に重なる
  carryNode("badge", { x: 113, y: -12 }, "alt");

  expect(distanceLabels("snap-gap")).toEqual([]);
  expect(sortedFacingDistanceLabels()).toEqual(["12", "150", "190", "66"]);
  expect(snapGuides()).toHaveLength(1);
});

test("揃え先との隙間と同じ線になる向きは、距離だけを出す", () => {
  renderCanvas({ selection: setupSiblings() });
  drawnApart();

  /*
   * 左辺が `card` の左辺（200）へ寄り、左右 200〜220・上下 72〜84 になる。下は揃え先 `card`
   * との隙間と同じ線になるので、隙間を出さず距離 66 を出す。
   */
  carryNode("badge", { x: 60, y: -12 }, "alt");

  expect(distanceLabels("snap-gap")).toEqual([]);
  expect(sortedFacingDistanceLabels()).toEqual(["100", "12", "240", "66"]);
});

test("Alt を押していても、距離と同じ線上に重ならない揃え先との隙間は出したまま", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  // 左辺が `first` の右辺 200 へ寄り、上下 200〜340。`first` の下辺 140 との隙間 60
  carrySecond({ x: -29, y: 200 }, "alt");

  expect(distanceLabels("snap-gap")).toEqual(["60"]);
  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("揃え先との隙間と同じ線になる向きは、距離だけを出す", () => {
  renderCanvas({ selection: setupSelection() });
  drawnAt("first", { left: 0, top: 0, width: 200, height: 140 });
  drawnFollowingFrame("second");
  drawnAt("third", { left: 464, top: 230, width: 200, height: 140 });

  /*
   * 左辺が `first` の左辺 0 へ寄り、左右 0〜200・上下 200〜340。上は `first` との隙間 60 と
   * 同じ線になるので隙間を出さず、上の距離 60 と右の `third` の左辺までの 264 を出す。
   */
  carrySecond({ x: -229, y: 200 }, "alt");

  expect(distanceLabels("snap-gap")).toEqual([]);
  expect(sortedFacingDistanceLabels()).toEqual(["264", "60"]);
});

isCoinciding(line: ThinLine, other: ThinLine): boolean {
  const isSameAlong = line.along === other.along;
  const isSpanIntersecting =
    Range.intersectionLength(line.span, other.span) > 0;
  const isAtClose = Math.abs(line.at - other.at) <= CoincidingThresholdPx;
  return isSameAlong && isSpanIntersecting && isAtClose;
},
